@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:stocktake-acceptance;DB_CLOSE_DELAY=-1;MODE=MYSQL")
@AutoConfigureMockMvc @ActiveProfiles("test")
public class StocktakeServiceTest {
    @Autowired StocktakeService stock;@Autowired StocktakeResolutionService resolutions;@Autowired StocktakeProjection projection;
    @Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired JwtTokenProvider tokens;
    @Autowired BookCopyActionService actions;@Autowired BorrowRecordService borrows;@Autowired InventoryIntakeService intakes;
    @Autowired BookMapper books;@Autowired BookCopyMapper copies;@Autowired LocationMaintenanceService locations;
    StocktakeService.Actor admin=new StocktakeService.Actor(101,true,false),clerk=new StocktakeService.Actor(102,false,true),other=new StocktakeService.Actor(103,false,true),readerActor=new StocktakeService.Actor(104,false,false);
    protected String unique(){return UUID.randomUUID().toString();}
    @BeforeEach void actors(){for(String role:List.of("ADMIN","LIBRARIAN","READER"))if(jdbc.queryForObject("SELECT COUNT(*) FROM sys_user WHERE username=?",Long.class,"stocktake-"+role)==0)jdbc.update("INSERT INTO sys_user(username,password,role,status) VALUES (?,'synthetic-only',?,1)","stocktake-"+role,role);}
    long member(){return insert(jdbc,"INSERT INTO sys_user(username,password,role,status) VALUES (?,'synthetic-only','READER',1)","stocktake-"+unique());}
    protected long book(){return insert(jdbc,"INSERT INTO book(isbn,title,stock_total,stock_available,status) VALUES (?,?,1,1,1)",unique().substring(0,18),"合成盘点书目");}
    protected long copy(long book,String barcode){return insert(jdbc,"INSERT INTO book_copy(book_id,barcode,status) VALUES (?,?,'AVAILABLE')",book,barcode);}
    ObjectNode base(long revision){return obj("operationKey",unique(),"expectedRevision",revision,"reason","合成人工核对依据");}
    JsonNode create(long... copies){return stock.create(obj("operationKey",unique(),"scope",obj("kind","COPY_SET","copyIds",copies),"campaignKey",null,"reason","合成范围"),clerk).path("result").path("session");}
    JsonNode event(String raw,String client){return obj("clientEventKey",client,"rawBarcode",raw,"observedPlacement",obj("kind","UNASSIGNED"),"clientObservedAt",null);}
    JsonNode scan(long session,long revision,JsonNode...events){ObjectNode in=base(revision);in.set("events",tree(events));return stock.observe(session,in,clerk);}
    JsonNode prepare(long id,long rev,String completion){return stock.check(id,base(rev).put("completionKind",completion),clerk,true).path("result").path("review");}
    ObjectNode confirmation(JsonNode review){return base(review.path("sourceRevision").asLong()).put("reviewSnapshotId",review.path("snapshotId").asLong()).put("previewDigest",review.path("digest").asText());}
    JsonNode acceptAll(long id,long rev){JsonNode check=stock.check(id,base(rev),clerk,false).path("result").path("review");if(check.path("changes").isEmpty())return stock.get(id,clerk);List<JsonNode>items=new ArrayList<>();for(JsonNode c:check.path("changes"))items.add(obj("entityKey",c.path("entityKey"),"changeToken",c.path("changeToken"),"expectedSignatureDigest",c.path("expectedSignatureDigest"),"decision","CONFIRM_EXPLANATION","evidence","人工逐项核对当前事实"));ObjectNode in=base(rev);in.set("items",tree(items));return stock.recheck(id,in,clerk).path("result").path("session");}
    void reason(String code,Runnable action){Failure e=assertThrows(Failure.class,action::run);assertEquals(code,e.code);}
    JsonNode move(long id,String text){JsonNode r=obj("schemaVersion",2,"idempotencyKey",unique(),"action","MOVE","reason","synthetic original workflow","copies",List.of(obj("copyId",id,"expectedVersion",copies.selectById(id).getActionVersion(),"targetLocation",obj("kind","TEXT","text",text))));var p=actions.previewV2(r,admin.id(),true);BookCopyActionContracts.ConfirmRequest confirm=new BookCopyActionContracts.ConfirmRequest();confirm.setIdempotencyKey(r.path("idempotencyKey").asText());confirm.setPreviewDigest(p.previewDigest());return tree(actions.confirmAny(p.requestId(),confirm,admin.id(),true));}

    @Test void exactObservationDuplicateCorrectionCoverageSealAndReplayNeverChangeInventory(){String exact="00001"+unique()+" ";long b=book(),c=copy(b,exact);var before=jdbc.queryForMap("SELECT * FROM book_copy WHERE id=?",c);JsonNode s=create(c);long id=s.path("sessionId").asLong();String key=unique();JsonNode e=event(exact,key);JsonNode first=scan(id,0,e,event(exact,unique()),event(exact.strip(),unique()),event("   ",unique()),event("😀".repeat(65),unique()));assertEquals(1,first.path("revision").asLong());long oid=first.path("result").path("observationIds").get(0).asLong();JsonNode replay=scan(id,1,e);assertEquals(1,replay.path("revision").asLong());assertEquals(oid,replay.path("result").path("observationIds").get(0).asLong());reason("IDEMPOTENCY_KEY_REUSED",()->scan(id,1,event("changed",key)));
        ObjectNode correction=base(1).put("observationId",oid).put("kind","VOID").putNull("replacement");stock.correct(id,correction,clerk);reason("REVISION_CONFLICT",()->stock.correct(id,base(2).put("observationId",oid).put("kind","VOID").putNull("replacement"),clerk));ObjectNode coverage=base(2);coverage.set("items",tree(List.of(obj("scopeItemId",c,"status","COMPLETE"))));stock.coverage(id,coverage,clerk);JsonNode p=prepare(id,3,"COMPLETE_SCOPE");assertTrue(p.path("changes").isEmpty(),write(p.path("changes")));ObjectNode confirm=confirmation(p);JsonNode receipt=stock.confirm(id,confirm,admin);assertEquals(receipt,stock.confirm(id,confirm,admin));assertEquals(receipt,stock.byKey(confirm.path("operationKey").asText(),admin));assertEquals("FINALIZED",stock.get(id,other).path("state").asText());assertEquals(write(before),write(jdbc.queryForMap("SELECT * FROM book_copy WHERE id=?",c)));assertEquals(1,jdbc.queryForObject("SELECT stock_available FROM book WHERE id=?",Integer.class,b));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM stock_flow WHERE book_id=?",Integer.class,b));assertEquals(5,stock.observations(id,1,100,null,"SCAN",clerk).path("total").asInt());}
    @Test void creationReplayAndScopeAndAdministrativePermissionsAreStrict(){long b=book(),c=copy(b,unique());ObjectNode in=obj("operationKey",unique(),"scope",obj("kind","COPY_SET","copyIds",List.of(c)),"campaignKey",null,"reason","合成创建");JsonNode receipt=stock.create(in,clerk);assertEquals(receipt,stock.create(in,clerk));long id=receipt.path("sessionId").asLong();reason("OWNER_REQUIRED",()->stock.get(id,other));reason("STOCKTAKE_ROLE_REQUIRED",()->stock.get(id,readerActor));JsonNode p=prepare(id,0,"PARTIAL");reason("STOCKTAKE_ROLE_REQUIRED",()->stock.confirm(id,confirmation(p),clerk));reason("INVALID_INPUT",()->stock.create(in.deepCopy().put("extra",true),clerk));reason("INVALID_INPUT",()->stock.observe(id,base(0).set("events",tree(List.of(event("\u0001",unique())))),clerk));reason("INVALID_INPUT",()->stock.check(id,base(0).put("expectedRevision","0"),clerk,false));stock.confirm(id,confirmation(p),admin);reason("ALREADY_FINALIZED",()->stock.confirm(id,confirmation(p),admin));reason("STOCKTAKE_ROLE_REQUIRED",()->stock.byKey(in.path("operationKey").asText(),readerActor));}
    @Test void fullScopeRequiresExplicitCoverageAndPartialPreservesUncoveredScope(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();JsonNode p=prepare(id,0,"COMPLETE_SCOPE");reason("COVERAGE_INCOMPLETE",()->stock.confirm(id,confirmation(p),admin));JsonNode partial=prepare(id,0,"PARTIAL");assertEquals("NOT_ATTEMPTED",partial.path("coverage").get(0).path("status").asText());JsonNode r=stock.confirm(id,confirmation(partial),admin);assertEquals("PARTIAL",r.path("result").path("receipt").path("completionKind").asText());}
    @Test void borrowReturnAndRenewAndLocationAbaRequireExplicitFreshRecheck(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();JsonNode p=prepare(id,0,"PARTIAL");BorrowRequest br=new BorrowRequest();br.setBookId(b);br.setCopyId(c);br.setUserId(member());BorrowRecord loan=borrows.borrow(br);borrows.renew(loan.getId(),1);borrows.returnBook(loan.getId());reason("STOCKTAKE_CHANGED",()->stock.confirm(id,confirmation(p),admin));JsonNode checked=acceptAll(id,0);assertEquals(1,checked.path("revision").asLong());JsonNode ready=prepare(id,1,"PARTIAL");assertTrue(ready.path("changes").isEmpty());move(c,"ABA away");move(c,"ABA original");reason("STOCKTAKE_CHANGED",()->stock.confirm(id,confirmation(ready),admin));acceptAll(id,1);stock.confirm(id,confirmation(prepare(id,2,"PARTIAL")),admin);}
    @Test void repeatCheckDoesNotAcceptChangesAndExpiredTokenFails(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();move(c,"new position");JsonNode first=stock.check(id,base(0),clerk,false).path("result").path("review");JsonNode repeated=stock.check(id,base(0),clerk,false).path("result").path("review");assertEquals(first.path("changes"),repeated.path("changes"));assertFalse(first.path("changes").isEmpty());List<JsonNode>items=new ArrayList<>();for(JsonNode cng:first.path("changes"))items.add(obj("entityKey",cng.path("entityKey"),"changeToken",cng.path("changeToken"),"expectedSignatureDigest",cng.path("expectedSignatureDigest"),"decision","CONFIRM_EXPLANATION","evidence","合成核对"));move(c,"another position");reason("RECHECK_STALE",()->stock.recheck(id,base(0).set("items",tree(items)),clerk));assertEquals(0,stock.get(id,clerk).path("revision").asLong());}
    @Test void reportExportIsSafeAndFormulaEscapedWithoutLosingBarcodeBytes(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();String raw="=1+1<script>literal</script> ";scan(id,0,event(raw,unique()));JsonNode p=prepare(id,1,"PARTIAL");stock.confirm(id,confirmation(p),admin);JsonNode export=resolutions.export(id,p.path("snapshotId").asLong(),other);assertFalse(write(export).contains("userId"));assertFalse(write(export).contains("password"));String csv=new String(resolutions.csv(export),java.nio.charset.StandardCharsets.UTF_8);assertTrue(csv.startsWith("\uFEFF"));assertTrue(csv.contains("'=1+1<script>literal</script> "));assertTrue(csv.contains(b64(raw)));assertTrue(write(export).contains(raw));}
    @Test void noActionResolutionPreservesFinalReceiptAndSuccessfulKeysReplay(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();JsonNode p=prepare(id,0,"PARTIAL");stock.confirm(id,confirmation(p),admin);String finalBefore=jdbc.queryForObject("SELECT final_receipt_json FROM stocktake_session WHERE id=?",String.class,id);ObjectNode in=obj("operationKey",unique(),"sessionId",id,"differenceIds",List.of(p.path("differenceIds").get(0).asLong()),"decision","NO_ACTION_WITH_REASON","workflow",null,"candidateId",null,"reason","人工核实无需动作");JsonNode r=resolutions.resolve(in,admin);assertEquals(r,resolutions.resolve(in,admin));assertEquals("NO_ACTION",r.path("result").path("resolution").path("state").asText());assertEquals(finalBefore,jdbc.queryForObject("SELECT final_receipt_json FROM stocktake_session WHERE id=?",String.class,id));reason("STOCKTAKE_ROLE_REQUIRED",()->resolutions.resolve(in,clerk));}
    @Test void httpUsesLiteralUnicodeAndRealRoleStatusAnd404Recovery()throws Exception{long b=book(),c=copy(b,unique());Long actor=jdbc.queryForObject("SELECT id FROM sys_user WHERE username='stocktake-LIBRARIAN'",Long.class);String token=tokens.generateToken(actor,"stocktake-LIBRARIAN","LIBRARIAN",0L);String input=write(obj("operationKey",unique(),"scope",obj("kind","COPY_SET","copyIds",List.of(c)),"campaignKey",null,"reason","合成HTTP"));var response=mvc.perform(post("/stocktakes").header("Authorization","Bearer "+token).contentType("application/json").content(input)).andReturn().getResponse();assertEquals(200,response.getStatus(),response.getContentAsString());long id=read(response.getContentAsString()).path("data").path("sessionId").asLong();ObjectNode scan=base(0);scan.set("events",tree(List.of(event("javascript: <script>字面</script>😀 ",unique()))));response=mvc.perform(post("/stocktakes/"+id+"/observations").header("Authorization","Bearer "+token).contentType("application/json").content(write(scan))).andReturn().getResponse();assertEquals(200,response.getStatus(),response.getContentAsString());assertEquals(401,mvc.perform(get("/stocktakes/"+id)).andReturn().getResponse().getStatus());assertEquals(404,mvc.perform(get("/stocktakes/operations/by-key").param("key",unique()).header("Authorization","Bearer "+token)).andReturn().getResponse().getStatus());}
    @Test void scanAfterNewBorrowDoesNotAcceptTheNewLoanSignature(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();BorrowRequest request=new BorrowRequest();request.setBookId(b);request.setCopyId(c);request.setUserId(member());BorrowRecord loan=borrows.borrow(request);scan(id,0,event(copies.selectById(c).getBarcode(),unique()));borrows.returnBook(loan.getId());JsonNode review=prepare(id,1,"PARTIAL");assertTrue(longs(review.path("graph").path("recordIds")).contains(loan.getId()));boolean pending=false;for(JsonNode change:review.path("changes"))if(change.path("entityKey").asText().equals("LOAN:"+loan.getId()))pending=true;assertTrue(pending);reason("STOCKTAKE_CHANGED",()->stock.confirm(id,confirmation(review),admin));acceptAll(id,1);stock.confirm(id,confirmation(prepare(id,2,"PARTIAL")),admin);}
    @Test void relatedCopyOverflowRollsBackWholeScanBatch(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();List<JsonNode>events=new ArrayList<>();for(int i=0;i<100;i++){String raw=unique();copy(b,raw);events.add(event(raw,unique()));}ObjectNode in=base(0);in.set("events",tree(events));reason("SCOPE_TOO_LARGE",()->stock.observe(id,in,clerk));assertEquals(0,stock.observations(id,1,100,null,null,clerk).path("total").asInt());assertEquals(0,stock.get(id,clerk).path("revision").asLong());reason("OPERATION_NOT_FOUND",()->stock.byKey(in.path("operationKey").asText(),clerk));}
    @Test void correctedReplacementAppendsOriginalEvidenceAndKnownOutsideScope(){long b=book(),c=copy(b,unique()),outside=copy(b,unique());long id=create(c).path("sessionId").asLong();JsonNode scanned=scan(id,0,event("mistake",unique()));long observation=scanned.path("result").path("observationIds").get(0).asLong();ObjectNode in=base(1).put("kind","CORRECTION").put("observationId",observation);in.set("replacement",obj("rawBarcode",copies.selectById(outside).getBarcode(),"observedPlacement",obj("kind","TEXT","text","  "),"clientObservedAt",null));stock.correct(id,in,clerk);JsonNode facts=stock.observations(id,1,100,null,null,clerk);assertEquals(2,facts.path("total").asInt());assertEquals("mistake",facts.path("records").get(0).path("rawBarcode").asText());assertFalse(facts.path("records").get(0).path("active").asBoolean());JsonNode p=prepare(id,2,"PARTIAL");assertEquals(1,stock.differences(id,p.path("snapshotId").asLong(),"KNOWN_COPY_OUTSIDE_SCOPE",outside,1,100,clerk).path("total").asInt());}
    @Test void expiredPreviewDoesNotSealAndRoleDowngradeCannotReplaySensitiveReceipt()throws Exception{long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();JsonNode prepared=prepare(id,0,"PARTIAL");jdbc.update("UPDATE stocktake_snapshot SET expires_at='2000-01-01' WHERE id=?",prepared.path("snapshotId").asLong());ObjectNode expired=prepared.deepCopy();expired.put("expiresAt","2000-01-01T00:00:00Z");jdbc.update("UPDATE stocktake_snapshot SET snapshot_json=? WHERE id=?",write(expired),prepared.path("snapshotId").asLong());reason("PREVIEW_EXPIRED",()->stock.confirm(id,confirmation(prepared),admin));Long actor=jdbc.queryForObject("SELECT id FROM sys_user WHERE username='stocktake-ADMIN'",Long.class);var active=new StocktakeService.Actor(actor,true,false);ObjectNode confirm=confirmation(prepare(id,0,"PARTIAL"));stock.confirm(id,confirm,active);String token=tokens.generateToken(actor,"stocktake-ADMIN","ADMIN",0L);jdbc.update("UPDATE sys_user SET role='LIBRARIAN' WHERE id=?",actor);try{assertEquals(403,mvc.perform(get("/stocktakes/operations/by-key").param("key",confirm.path("operationKey").asText()).header("Authorization","Bearer "+token)).andReturn().getResponse().getStatus());}finally{jdbc.update("UPDATE sys_user SET role='ADMIN' WHERE id=?",actor);}}
    void complete(long id,long revision,long copy){ObjectNode in=base(revision);in.set("items",tree(List.of(obj("scopeItemId",copy,"status","COMPLETE"))));stock.coverage(id,in,clerk);}
    @Test void activeLoanAnomalyNeverBecomesMissingCandidateEvenWithCompleteCoverage(){long b=book(),c=copy(b,unique());jdbc.update("INSERT INTO borrow_record(user_id,book_id,copy_id,borrow_date,due_date,status) VALUES (?,?,?,CURRENT_DATE,CURRENT_DATE,'BORROWING')",member(),b,c);long id=create(c).path("sessionId").asLong();complete(id,0,c);JsonNode p=prepare(id,1,"COMPLETE_SCOPE");assertEquals(0,stock.differences(id,p.path("snapshotId").asLong(),"MISSING_CANDIDATE",c,1,100,clerk).path("total").asInt());assertEquals(1,stock.differences(id,p.path("snapshotId").asLong(),"LOAN_LINK_ANOMALY",c,1,100,clerk).path("total").asInt());}
    @Test void pendingChangesSuppressMissingCandidateUntilExplicitFreshRecheck(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();complete(id,0,c);move(c,"new place");JsonNode p=prepare(id,1,"COMPLETE_SCOPE");assertFalse(p.path("changes").isEmpty());assertEquals(0,stock.differences(id,p.path("snapshotId").asLong(),"MISSING_CANDIDATE",c,1,100,clerk).path("total").asInt());acceptAll(id,1);JsonNode clean=prepare(id,2,"COMPLETE_SCOPE");assertEquals(1,stock.differences(id,clean.path("snapshotId").asLong(),"MISSING_CANDIDATE",c,1,100,clerk).path("total").asInt());}
    @Test void wrongObservedPlaceIsMisplacedWithoutObservedMatch(){long b=book(),c=copy(b,unique());long id=create(c).path("sessionId").asLong();ObjectNode e=(ObjectNode)event(copies.selectById(c).getBarcode(),unique());e.set("observedPlacement",obj("kind","TEXT","text","different physical place"));scan(id,0,e);JsonNode p=prepare(id,1,"PARTIAL");assertEquals(1,stock.differences(id,p.path("snapshotId").asLong(),"MISPLACED_CANDIDATE",c,1,100,clerk).path("total").asInt());assertEquals(0,stock.differences(id,p.path("snapshotId").asLong(),"OBSERVED_MATCH",c,1,100,clerk).path("total").asInt());}
    @ParameterizedTest
    @ValueSource(strings={"", "/snapshots/1", "/observations", "/differences", "/changes", "/resolutions",
            "/export?reviewSnapshotId=1&format=json", "/export?reviewSnapshotId=1&format=csv"})
    void missingSessionHttpChecksRoleBeforeLookingUpObject(String suffix)throws Exception {
        String path="/stocktakes/"+Long.MAX_VALUE+suffix;
        for(String role:List.of("READER","ADMIN","LIBRARIAN")) {
            Long actor=jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?",Long.class,"stocktake-"+role);
            String token=tokens.generateToken(actor,"stocktake-"+role,role,0L);
            var response=mvc.perform(get(path).header("Authorization","Bearer "+token)).andReturn().getResponse();
            int expected=role.equals("READER")?403:404;
            assertEquals(expected,response.getStatus(),role+" "+path+": "+response.getContentAsString());
            JsonNode body=read(response.getContentAsString());
            assertEquals(expected,body.path("code").asInt());
            assertEquals(role.equals("READER")?"STOCKTAKE_ROLE_REQUIRED":"STOCKTAKE_NOT_FOUND",
                    body.path("data").path("reasonCode").asText());
        }
        assertEquals(401,mvc.perform(get(path)).andReturn().getResponse().getStatus(),path);
    }
    @Test void missingSessionServiceChecksRoleBeforeLookingUpObject() {
        long missing=Long.MAX_VALUE;
        List<java.util.function.Function<StocktakeService.Actor,JsonNode>>reads=List.of(
                a->stock.get(missing,a),a->stock.snapshot(missing,1,a),
                a->stock.observations(missing,1,20,null,null,a),
                a->stock.differences(missing,null,null,null,1,20,a),
                a->stock.changes(missing,null,null,null,1,20,a),
                a->resolutions.page(missing,1,20,a),a->resolutions.export(missing,1,a));
        for(var read:reads) {
            reason("STOCKTAKE_ROLE_REQUIRED",()->read.apply(readerActor));
            reason("STOCKTAKE_NOT_FOUND",()->read.apply(admin));
            reason("STOCKTAKE_NOT_FOUND",()->read.apply(clerk));
        }
    }
}
